CREATE TEMP TABLE showcase_projects_to_enrich ON COMMIT DROP AS
SELECT i.id, i.company_id, d.number, d.artifact, d.criterion, d.next_step
FROM showcase_detail d
JOIN initiatives i ON i.id = format('92000002-0000-4000-8000-%s', lpad(d.number::text, 12, '0'))::uuid
    AND i.company_id = format('92000001-0000-4000-8000-%s', lpad((d.number / 100)::text, 12, '0'))::uuid;

DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM showcase_projects_to_enrich WHERE number = 101) THEN
        RAISE EXCEPTION 'load the KIT showcase before enriching it';
    END IF;
END
$$;

-- An exact match against a legacy fixture action keeps existing project edits intact.
UPDATE initiatives i
SET next_step = p.next_step || '.'
FROM showcase_projects_to_enrich p
WHERE i.id = p.id AND i.next_step IN (
    'Сверить готовность подразделений и подтвердить следующий этап внедрения.',
    'Согласовать с заказчиком критерии пилота и список контрольных площадок.',
    'Передать результаты эксплуатации ответственному за сопровождение.',
    'Найти владельцев процесса и назначить первую встречу по требованиям.',
    'Уточнить ограничения и вынести план работ на согласование.'
);

