-- Workspace edits increment the contact version, even for project-only changes.
-- Lock those version rows before enriching the participation so a concurrent editor wins.
WITH enrichment AS MATERIALIZED (
    SELECT p.initiative_id, p.contact_id,
           CASE WHEN p.decision_maker THEN w.mandate END AS mandate,
           format('%s. Рабочий предмет — %s.', w.interest, project.artifact) AS interest,
           format('Матрица проектных ролей · %s', w.department) AS source_label
    FROM initiative_participants p
    JOIN showcase_projects_to_enrich project ON project.id = p.initiative_id AND project.company_id = p.company_id
    JOIN contacts c ON c.id = p.contact_id AND c.company_id = p.company_id
    JOIN departments d ON d.id = c.department_id AND d.company_id = c.company_id
    JOIN showcase_workstream_evidence w ON d.name = w.department
        AND d.id = format('92000003-0000-4000-8000-%s', lpad(((project.number / 100) * 100 + w.number)::text, 12, '0'))::uuid
    WHERE c.id::text LIKE '92000004-0000-4000-8000-%' AND c.edit_version = 0
        AND p.influence_basis IN (
            'Утверждает лимит программы и перенос затрат между этапами.',
            'Согласует условия договора и принимает решение о запуске закупки.',
            'Представляет программу на управляющем комитете и утверждает приоритеты.',
            format('Утверждает решения направления «%s» перед передачей в проектный офис.', w.department),
            format('Готовит экспертные заключения. Область ответственности — %s.', w.topic),
            'Собирает требования подразделения и участвует в приёмке.',
            'Консультирует по рабочему процессу и проверяет результат на площадке.'
        )
        AND ((p.decision_maker AND p.mandate IS NULL) OR p.interest IS NULL OR p.source_label IS NULL)
    ORDER BY c.id
    FOR UPDATE OF c
)
UPDATE initiative_participants p
SET mandate = coalesce(p.mandate, enrichment.mandate),
    interest = coalesce(p.interest, enrichment.interest),
    source_label = coalesce(p.source_label, enrichment.source_label)
FROM enrichment
WHERE p.initiative_id = enrichment.initiative_id AND p.contact_id = enrichment.contact_id;

-- Compare the entire legacy record before changing its narrative. Match the source channel
-- and preserve its value, as well as the date, author, manager and linked participants.
