) AS template(number, type, subject, outcome, next_step, comment);

WITH enrichment AS (
    SELECT t.id, code.slot, code.sequence, w.focus, p.artifact, p.criterion, p.next_step,
           original.number AS template_number, original.subject, w.topic,
           original.outcome AS original_outcome, original.next_step AS original_next_step,
           original.comment AS original_comment,
           CASE t.type WHEN 'EMAIL' THEN 'Корпоративная переписка'
                       WHEN 'NOTE' THEN 'Журнал решений'
                       WHEN 'PROPOSAL' THEN 'Реестр предложений'
                       ELSE 'Журнал взаимодействий' END AS original_source
    FROM touchpoints t
    JOIN showcase_projects_to_enrich p ON p.id = t.initiative_id
    CROSS JOIN LATERAL (
        SELECT substring(t.id::text FROM '^92000006-0000-4000-8000-([0-9]{12})$')::bigint AS number
    ) seed
    CROSS JOIN LATERAL (
        SELECT (seed.number % 100000 / 100)::integer AS slot, (seed.number % 100)::integer AS sequence
    ) code
    JOIN showcase_workstream_evidence w ON split_part(t.subject, ' · ', 2) = w.topic
    JOIN showcase_legacy_touchpoints original ON original.type = t.type AND original.number = CASE
        WHEN code.sequence = 0 THEN 11
        WHEN code.sequence >= 8 THEN 7 + (code.sequence + code.slot) % 4
        ELSE (code.slot * 7 + code.sequence * 11 + w.number) % 15 + 1 END
    WHERE seed.number / 100000 = p.number
)
UPDATE touchpoints t
SET subject = format('%s · %s', e.subject, e.artifact),
    outcome = CASE WHEN t.outcome IS NOT NULL THEN CASE e.template_number
        WHEN 1 THEN format('На контрольной встрече разобрали %s. В протокол внесли критерий: %s.', e.focus, e.criterion)
        WHEN 2 THEN format('Выделили риск для контура «%s». До оценки зависимости держат открытым условие: %s.', e.focus, e.criterion)
        WHEN 3 THEN format('Получили замечания к разделу «%s». В пакет правок включили условие: %s.', e.focus, e.criterion)
        WHEN 4 THEN format('Сверили выборку по направлению «%s». Отдельно отметили строки, по которым проверяют, что %s.', e.focus, e.criterion)
        WHEN 5 THEN format('Разложили «%s» на обязательные работы и резерв. Оценку привязали к условию: %s.', e.artifact, e.criterion)
        WHEN 6 THEN format('На стенде показали «%s». Повторный прогон должен доказать, что %s.', e.artifact, e.criterion)
        WHEN 7 THEN format('Владелец процесса описал исключения по теме «%s». Критерий проверки — %s.', e.focus, e.criterion)
        WHEN 8 THEN format('Получены первые материалы по теме «%s». Для проверки, что %s, потребуется ещё одна выгрузка.', e.focus, e.criterion)
        WHEN 9 THEN format('Сверили текущие записи по теме «%s» и вынесли на повторную проверку условие: %s.', e.focus, e.criterion)
        WHEN 10 THEN format('В обследование включили «%s». Первое интервью посвятят проверке, что %s.', e.artifact, e.criterion)
        WHEN 11 THEN format('Разделили ответственность за этапы переключения. Условие перед запуском — %s.', e.criterion)
        WHEN 12 THEN format('Сверили доступность команды и поставщика. В резервном окне проверят, что %s.', e.criterion)
        WHEN 13 THEN format('В переписке подтвердили критерий приёмки: %s.', e.criterion)
        WHEN 14 THEN format('Комитет оставил решение с оговоркой: переход состоится, когда подтвердят, что %s.', e.criterion)
        WHEN 15 THEN format('Сравнили поэтапный запуск и пилот для контура «%s». Для обоих вариантов действует условие: %s.', e.artifact, e.criterion)
    END END,
    next_step = CASE WHEN t.next_step IS NOT NULL THEN CASE e.template_number
        WHEN 2 THEN format('Запросить оценку риска и описать, что произойдёт при нарушении условия: %s.', e.criterion)
        WHEN 3 THEN format('Передать обновлённый раздел «%s» на проверку по условию: %s.', e.focus, e.criterion)
        WHEN 4 THEN format('Приложить к разделу «%s» контрольную выборку, по которой можно проверить, что %s.', e.focus, e.criterion)
        WHEN 6 THEN format('Подготовить повторный прогон, в котором можно проверить, что %s.', e.criterion)
        WHEN 7 THEN format('Добавить исключения в описание процесса и сверить с владельцем условие: %s.', e.criterion)
        WHEN 8 THEN format('Запросить журнал контрольного примера, по которому можно проверить, что %s.', e.criterion)
        WHEN 9 THEN format('Принести на сверку расхождения по теме «%s» и выбрать случай, где можно проверить, что %s.', e.focus, e.criterion)
        WHEN 10 THEN format('Пригласить владельца процесса и разобрать, как проверить, что %s.', e.criterion)
        WHEN 11 THEN format('Зафиксировать состав дежурной смены и назначить окно, в котором можно проверить, что %s.', e.criterion)
        WHEN 12 THEN format('Подтвердить у поставщика, что резервного окна хватит на проверку условия: %s.', e.criterion)
        WHEN 13 THEN format('Приложить контрольный пример, показывающий, что %s.', e.criterion)
        ELSE e.next_step || '.'
    END END,
    comment = CASE WHEN t.comment IS NOT NULL THEN format('%s Тема разбора — %s.', e.original_comment, e.focus) END
FROM enrichment e
WHERE t.id = e.id AND t.subject = format('%s · %s', e.subject, e.topic)
    AND t.source_label = e.original_source AND t.request_fingerprint IS NULL
    AND (t.created_by IS NULL OR t.created_by = 'showcase-import')
    AND t.outcome IS NOT DISTINCT FROM (
        CASE WHEN e.sequence > 0 AND (e.slot + e.sequence) % 9 <> 0 THEN e.original_outcome END)
    AND t.next_step IS NOT DISTINCT FROM (
        CASE WHEN (e.slot + e.sequence) % 7 <> 0 THEN e.original_next_step END)
    AND t.comment IS NOT DISTINCT FROM (
        CASE WHEN (e.slot + e.sequence) % 5 IN (0, 2) THEN e.original_comment END);

-- Keep source authors and dates intact and enrich only the seed's exact stock reasoning.
UPDATE stance_revisions s
SET basis = format('%s Для проекта обсуждали, как подтвердить, что %s.', s.basis, p.criterion)
FROM showcase_projects_to_enrich p
WHERE s.initiative_id = p.id AND s.changed_by = 'showcase-import' AND s.basis IN (
    'Поддерживает пилот после проверки расчётов и согласования состава команды.',
    'Просит подтвердить готовность площадок и оценить нагрузку на операционную команду.',
    'Ожидает результаты обследования перед тем, как сформулировать позицию.',
    'Возражает против запуска в предложенное окно из-за пересечения с плановыми работами.',
    'Готов выделить специалистов подразделения на контрольные испытания.',
    'Предлагает сократить объём первого этапа до согласования критериев приёмки.',
    'Просит учесть требования смежной службы и вынести решение на следующую встречу.',
    'Подтвердил интерес после демонстрации перехода на новый процесс.'
);

COMMIT;
